import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { LockOpen } from 'lucide-react';
import ToolLayout from '@/components/tools/ToolLayout';
import UploadBox from '@/components/tools/pdf-to-jpg/UploadBox';
import PasswordField from '@/components/tools/pdf-security/PasswordField';
import ProcessResult from '@/components/tools/pdf-security/ProcessResult';
import SetupGate from '@/components/tools/pdf-security/SetupGate';
import { usePersistentState } from '@/hooks/usePersistentState';
import { unlockPdf } from '@/lib/pdf/unlock';

const UnlockPdf: FC = () => {
  const [file, setFile] = usePersistentState<File | null>('unlock-pdf:file', null);
  const [password, setPassword] = useState('');

  const [blob, setBlob] = useState<Blob | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setBlob(null);
    setError(null);
  }, [file, password]);

  const canGenerate = !!file && password.length > 0;

  const handleGenerate = () => {
    if (!file || !canGenerate) return;
    setError(null);
    setIsProcessing(true);
    unlockPdf(file, password)
      .then((result) => {
        setBlob(result);
        setIsProcessing(false);
      })
      .catch((err: Error) => {
        setError(err.message || "Couldn't unlock this PDF");
        setIsProcessing(false);
      });
  };

  const fileName = file ? `${file.name.replace(/\.pdf$/i, '') || 'document'}-unlocked.pdf` : 'unlocked.pdf';

  return (
    <ToolLayout
      title="Unlock PDF"
      description="Remove password protection from a PDF you already have the password for — entirely in your browser, nothing is uploaded anywhere."
    >
      <div className="max-w-2xl space-y-6">
        <UploadBox file={file} onSelect={setFile} onClear={() => setFile(null)} />

        {file && (
          <PasswordField
            label="Current password"
            value={password}
            onChange={setPassword}
            placeholder="Enter the PDF's password"
            autoComplete="current-password"
          />
        )}

        <SetupGate>
          <ProcessResult
            hasFile={!!file}
            blob={blob}
            fileName={fileName}
            isProcessing={isProcessing}
            processingLabel="Unlocking…"
            error={error}
            canGenerate={canGenerate}
            generateLabel="Unlock PDF"
            generateIcon={<LockOpen className="w-4 h-4" />}
            onGenerate={handleGenerate}
          />
        </SetupGate>
      </div>
    </ToolLayout>
  );
};

export default UnlockPdf;
