import { runQpdf, QpdfError } from './qpdf';

/** Removes password protection from a PDF, given the current password — qpdf itself
 * doesn't distinguish "wrong password" from most other decrypt failures in a way we
 * can reliably parse from its output, so any failure here is reported as a bad
 * password, which is by far the most common real-world cause. */
export async function unlockPdf(file: File, password: string): Promise<Blob> {
  const bytes = new Uint8Array(await file.arrayBuffer());
  try {
    const outBytes = await runQpdf(bytes, ['--decrypt', `--password=${password}`, '--', '{in}', '{out}']);
    return new Blob([outBytes], { type: 'application/pdf' });
  } catch {
    throw new QpdfError("Couldn't unlock this PDF — check the password and try again.");
  }
}
